#!/usr/bin/env node
/**
 * H38 Office Script Bundler
 * Concatenates the 176+ individual scripts into a few bundles to reduce HTTP requests.
 * Preserves exact load order from index.html. All scripts use globals (no ES modules),
 * so simple concatenation is safe.
 *
 * Usage: node scripts/bundle-office-scripts.js
 * Output: commercial-app/bundle-core.js, bundle-pages.js, bundle-features.js
 */

const fs = require('fs');
const path = require('path');

const APP_DIR = path.join(__dirname, '..', 'commercial-app');
const INDEX_HTML = path.join(APP_DIR, 'index.html');

// Scripts that must load before anything else (auth, db, config)
// These are identified by being in the first ~15 script tags
const CORE_PATTERNS = [
  'db.js', 'bridge.js', 'supabase-config.js', 'supabase-single-client.js',
  'supabase-auth.js', 'supabase-invite-activation.js', 'auth-session-guard.js',
  'supabase-session-recovery.js', 'auth-cache-guard.js',
];

// Page renderer scripts (app-*.js contain the main page logic)
const PAGE_PATTERNS = [
  /^app-\d+\.js$/,
];

function main() {
  const html = fs.readFileSync(INDEX_HTML, 'utf8');
  
  // Extract script srcs in order
  const scriptRe = /<script[^>]*src="(\.\/[^"]+)"[^>]*><\/script>/g;
  const scripts = [];
  let m;
  while ((m = scriptRe.exec(html)) !== null) {
    const src = m[1];
    // Skip external CDN scripts
    if (src.startsWith('http')) continue;
    // Skip the loader itself and bundles
    if (src.includes('h38-script-loader') || src.includes('bundle-')) continue;
    scripts.push(src);
  }

  console.log(`Found ${scripts.length} local scripts in index.html`);

  // Categorize
  const core = [];
  const pages = [];
  const features = [];

  for (const src of scripts) {
    const filename = path.basename(src).split('?')[0];
    if (CORE_PATTERNS.some(p => filename === p || filename.startsWith(p.replace('.js', '')))) {
      core.push(src);
    } else if (PAGE_PATTERNS.some(p => p.test(filename))) {
      pages.push(src);
    } else {
      features.push(src);
    }
  }

  console.log(`Core: ${core.length}, Pages: ${pages.length}, Features: ${features.length}`);

  // Bundle each category
  const bundles = [
    { name: 'bundle-core.js', scripts: core },
    { name: 'bundle-pages.js', scripts: pages },
    { name: 'bundle-features.js', scripts: features },
  ];

  const buildId = `20261011-bundled-1`;
  
  for (const bundle of bundles) {
    let output = `/* H38 Office Bundle: ${bundle.name} (build ${buildId})\n`;
    output += ` * Auto-generated by scripts/bundle-office-scripts.js\n`;
    output += ` * Contains ${bundle.scripts.length} scripts in original load order.\n */\n\n`;
    
    let totalSize = 0;
    for (const src of bundle.scripts) {
      const cleanSrc = src.split('?')[0];
      const filePath = path.join(APP_DIR, cleanSrc.replace('./', ''));
      if (!fs.existsSync(filePath)) {
        console.warn(`  WARNING: Not found: ${filePath}`);
        continue;
      }
      const content = fs.readFileSync(filePath, 'utf8');
      totalSize += content.length;
      output += `\n/* --- ${cleanSrc} --- */\n`;
      output += content;
      // Ensure file ends with semicolon/newline to prevent concatenation issues
      if (!output.endsWith('\n')) output += '\n';
      output += ';\n';
    }

    const outPath = path.join(APP_DIR, bundle.name);
    fs.writeFileSync(outPath, output);
    console.log(`Wrote ${bundle.name}: ${(output.length/1024).toFixed(0)} KB (${bundle.scripts.length} scripts)`);
  }

  console.log('\nDone. Update index.html to reference the bundles.');
  console.log('Build ID:', buildId);
}

main();
